import streamlit as st

JS = '''
export default function(component) {
  const { data, parentElement, setTriggerValue, setStateValue } = component;
  const box = document.createElement("div");
  box.innerHTML = data.options
    .map(o => `<button data-v="${o}">${o}</button>`).join(" ");
  box.querySelectorAll("button").forEach(b => {
    b.onclick = () => { setStateValue("choice", b.dataset.v);
                        setTriggerValue("clicked", b.dataset.v); };
  });
  parentElement.appendChild(box);
}
'''
picker = st.components.v2.component("choice_picker", js=JS,
                                    css="button { margin: 2px; }")

result = picker(data={"options": ["small", "medium", "large"]}, key="size",
                on_choice_change=lambda: None, on_clicked_change=lambda: None)
st.write("Persistent choice:", result.choice)
if result.clicked:
    st.toast(f"Clicked {result.clicked}")
st.html("<span style='color:#E8383D'>Static HTML, no iframe</span>")
